        "sourceText": "The teacher gives them time to rest after a long lesson and Tembe lies next to the teacher",
        "zh": "一节长长的课后，老师让大家休息，滕贝躺在老师身旁。",
        "tip": "可以一起放松一下身体。",
        "alt": "一节长长的课后，老师让大家休息，滕贝躺在老师身旁。",
        "sourceImage": "https://raw.githubusercontent.com/global-asp/asp-imagebank/a56e6dbe7aeeb8ea3e53d9941664416e2e7356ad/medium/0344/07.jpg",
        "sourceImageSha256": "51af8f2a8643b89e3e89ff41cac2b1b0a2f81d59f5f79cb05320beed6fdeb73c",
