        "sourceText": "when they wake up, the helps them cross the railway and get back home",
        "zh": "醒来后，老师帮助他们穿过铁轨，回家去。",
        "tip": "看看老师怎样带着孩子们走路。",
        "alt": "醒来后，老师帮助他们穿过铁轨，回家去。",
        "sourceImage": "https://raw.githubusercontent.com/global-asp/asp-imagebank/a56e6dbe7aeeb8ea3e53d9941664416e2e7356ad/medium/0344/08.jpg",
