        "imageHeight": 546,
        "audioFile": "audio/06-8594c09e2c3fc78f.mp3",
        "sourceAudio": "https://vanesacoding.github.io/say-it-today/books/library/0147/audio/06-8594c09e2c3fc78f.mp3",
