        "sourceText": "\"I do not have enough money for that shirt,\" says dad.",
        "zh": "爸爸说：“我没有足够的钱再买那件衬衫。”",
        "tip": "听听爸爸怎样解释。",
        "alt": "爸爸说：“我没有足够的钱再买那件衬衫。”",
