        "sourceText": "Hamisi's dad pays for the uniform. He is surprised when he gets the change. There is enough money left over to buy a shirt!",
        "zh": "爸爸付了校服的钱，拿到找零时很惊讶。剩下的钱竟然够买一件衬衫！",
        "tip": "看看找回来的零钱。",
