        "sourceText": "Look at the tall slide. Am I brave enough to climb up and slide down?",
        "zh": "看，那座高高的滑梯！我够勇敢，能爬上去再滑下来吗？",
        "tip": "聊聊面对高滑梯时是什么心情。",
        "alt": "看，那座高高的滑梯！我够勇敢，能爬上去再滑下来吗？",
