        "sourceText": "Mom and Dad need to push us when we want to swing. I am going to try to swing the highest.",
        "zh": "荡秋千时，要请爸爸妈妈推我们。我想试着荡得最高。",
        "tip": "看看谁在推秋千。",
        "alt": "荡秋千时，要请爸爸妈妈推我们。我想试着荡得最高。",
        "sourceImage": "https://raw.githubusercontent.com/global-asp/asp-imagebank/a56e6dbe7aeeb8ea3e53d9941664416e2e7356ad/medium/0181/05.jpg",
