        "sourceText": "Lighthouses are important at night and in the fog. They alert ships to the rocks in the sea.",
        "zh": "晚上和有雾的时候，灯塔很重要。它会提醒船只小心海里的礁石。",
        "tip": "看看灯塔怎样帮助海上的船。",
        "alt": "晚上和有雾的时候，灯塔很重要。它会提醒船只小心海里的礁石。",
        "sourceImage": "https://raw.githubusercontent.com/global-asp/asp-imagebank/a56e6dbe7aeeb8ea3e53d9941664416e2e7356ad/medium/0181/09.jpg",
        "sourceImageSha256": "755dd7fe8cf5b397880c9c36494df9f9b59af1ed7d66dc07e6f269309932dddf",
