        "sourceText": "We have had a happy time at the park, but now it is home time. We are going to catch a bus.",
        "zh": "我们在公园玩得很开心，现在该回家了。我们要去坐公共汽车。",
        "tip": "找找回家要坐的车。",
        "alt": "我们在公园玩得很开心，现在该回家了。我们要去坐公共汽车。",
