        "alt": "蜗牛把纸条分给朋友们，说：“兔子来叫我的时候，你们中就有一个回答：我是蜗牛。”",
        "sourceImage": "https://raw.githubusercontent.com/global-asp/asp-imagebank/a56e6dbe7aeeb8ea3e53d9941664416e2e7356ad/medium/0028/05.jpg",
        "sourceImageSha256": "d51c8a0ea5e0f1e40400cb1c576b435b984b8583900b050d93fc62513ffe3039",
